--- original/src/ViciOne.ServiceBus/Providers/Persistence/ReliableMessaging/ReliableMessagingDeliveryService.cs
+++ fixed/src/ViciOne.ServiceBus/Providers/Persistence/ReliableMessaging/ReliableMessagingDeliveryService.cs
@@ -28,6 +28,7 @@
     IOutboxStore<TBus> _store = null!;
     bool _compositionResolved;
     long _nextTelemetrySnapshotUtcTicks;
+    int _telemetrySnapshotHasNoSuccessor;

     public ReliableMessagingDeliveryService(
         IServiceProvider provider,
@@ -86,9 +87,11 @@
     {
         EnsureCompositionResolved();
         IReadOnlyList<DurableSendDelivery> batch = [];
+        DateTimeOffset? claimTime = null;
         if (_store != null)
         {
             DateTimeOffset now = _timeProvider.GetUtcNow();
+            claimTime = now;
             ReliableMessagingPolicy<TBus> policy = RequirePolicy();
             // Claim no more work than can begin immediately. A durable lease is ownership, not a local work buffer:
             // pre-claiming a larger batch would leave later records leased-but-idle behind a slow provider send.
@@ -124,8 +127,8 @@
             additionalWork |= await source.DeliverDueBatchAsync(cancellationToken).ConfigureAwait(false);
         }

-        if (_store != null)
-            await RefreshTelemetrySnapshotIfDueAsync(_timeProvider.GetUtcNow(), cancellationToken).ConfigureAwait(false);
+        if (claimTime is { } anchor)
+            await RefreshTelemetrySnapshotIfDueAsync(anchor, cancellationToken).ConfigureAwait(false);
         return batch.Count > 0 || additionalWork;
     }

--- original/src/ViciOne.ServiceBus/Providers/Persistence/ReliableMessaging/ReliableMessagingDeliveryService.Telemetry.cs
+++ fixed/src/ViciOne.ServiceBus/Providers/Persistence/ReliableMessaging/ReliableMessagingDeliveryService.Telemetry.cs
@@ -62,17 +62,19 @@
         }
     }

-    async Task RefreshTelemetrySnapshotIfDueAsync(DateTimeOffset now, CancellationToken cancellationToken)
+    async Task RefreshTelemetrySnapshotIfDueAsync(DateTimeOffset claimTime, CancellationToken cancellationToken)
     {
         long next = Volatile.Read(ref _nextTelemetrySnapshotUtcTicks);
-        if (now.UtcTicks < next)
+        if (Volatile.Read(ref _telemetrySnapshotHasNoSuccessor) != 0 || claimTime.UtcTicks < next)
             return;
-
-        // Advance first. If an observation read fails we try again at the configured cadence rather than hot-looping.
-        Volatile.Write(ref _nextTelemetrySnapshotUtcTicks, (now + RequirePolicy().TelemetrySnapshotInterval).UtcTicks);

         try
         {
+            // Reserve from the required claim time before any optional clock or storage read can fail.
+            ReserveTelemetrySnapshotSuccessor(claimTime);
+            DateTimeOffset now = _timeProvider.GetUtcNow();
+            // Delivery may be slow. Successful observations start the minimum interval at their actual UTC.
+            ReserveTelemetrySnapshotSuccessor(now);
             DurableSendStoreSnapshot snapshot = await _store.GetSnapshotAsync(cancellationToken).ConfigureAwait(false);
             _instrumentation.PublishDurableSnapshot(snapshot, now);
         }
@@ -84,6 +86,21 @@
         {
             TryLogTelemetrySnapshotFailed(DiagnosticTypeName(exception.GetType()));
         }
+    }
+
+    void ReserveTelemetrySnapshotSuccessor(DateTimeOffset basis)
+    {
+        long intervalTicks = RequirePolicy().TelemetrySnapshotInterval.Ticks;
+        if (intervalTicks > DateTimeOffset.MaxValue.UtcTicks - basis.UtcTicks)
+        {
+            // There is no later representable UTC. Allow this attempt, then stop repeated preparation at MaxValue.
+            Volatile.Write(ref _telemetrySnapshotHasNoSuccessor, 1);
+            return;
+        }
+
+        long successor = basis.UtcTicks + intervalTicks;
+        if (successor > Volatile.Read(ref _nextTelemetrySnapshotUtcTicks))
+            Volatile.Write(ref _nextTelemetrySnapshotUtcTicks, successor);
     }

     static string OutcomeTag(DurableSendDeliveryOutcome outcome)
